const LOGO="";

const UPSTREAM='https://pem-monarcas-estudos.tacyohenrique07.chatgpt.site';
function response(body,type,status=200){return new Response(body,{status,headers:{'Content-Type':type,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin'}})}
export default {async fetch(request){
 const incoming=new URL(request.url),raw=incoming.searchParams.get('__pem_path')||incoming.pathname,path=raw.startsWith('/')?raw:'/'+raw;
 if(['GET','HEAD'].includes(request.method)){
  if(path==='/')return response(request.method==='HEAD'?null:HTML,'text/html; charset=utf-8');
  if(path==='/app.js')return response(request.method==='HEAD'?null:JS,'application/javascript; charset=utf-8');
  if(path==='/asset/monarcas.webp')return response(request.method==='HEAD'?null:Buffer.from(LOGO,'base64'),'image/webp');
 }
 if(!['/api/login','/api/logout','/api/data'].includes(path)&&!path.startsWith('/asset/'))return response('Não encontrado','text/plain; charset=utf-8',404);
 const upstream=new URL(UPSTREAM);upstream.pathname=path;
 const headers=new Headers(request.headers);headers.delete('host');headers.delete('content-length');headers.delete('accept-encoding');
 if(!['GET','HEAD'].includes(request.method)){if(headers.get('origin')!==incoming.origin)return response('Origem inválida','text/plain',403);headers.set('origin',UPSTREAM)}
 try{
  const result=await fetch(upstream,{method:request.method,headers,body:['GET','HEAD'].includes(request.method)?undefined:await request.arrayBuffer(),redirect:'manual'});
  if(path==='/api/data'&&request.method==='GET'&&result.ok){const data=await result.json();data.syllabus.ARTES=EXTRA.lessons.filter(l=>l.subject==='ARTES').map(l=>l.title);data.syllabus['EDUCAÇÃO FÍSICA']=EXTRA.lessons.filter(l=>l.subject==='EDUCAÇÃO FÍSICA').map(l=>l.title);return response(JSON.stringify({...data,...EXTRA}),'application/json; charset=utf-8')}
  const out=new Headers(result.headers);out.delete('content-encoding');out.delete('content-length');out.set('Cache-Control','no-store');
  out.delete('set-cookie');for(const cookie of result.headers.getSetCookie()){if(cookie.startsWith('pem_session='))out.append('set-cookie',cookie)}
  return new Response(result.body,{status:result.status,headers:out});
 }catch{return response(JSON.stringify({error:'Não foi possível conectar. Tente novamente.'}),'application/json; charset=utf-8',502)}
}};